# Golden values for phn-epi sample_size.rs: stats::power.prop.test (equal groups,
# no continuity correction, which equals Fleiss's formula with r = 1) and
# stats::power.t.test (exact t-based; our normal + z^2/4 approximation must be
# within one subject after rounding up).
# Run: Rscript sample_size.R > ../sample_size.json
suppressPackageStartupMessages(library(jsonlite))
props <- list(c(0.10, 0.05, 0.80), c(0.30, 0.20, 0.90), c(0.50, 0.40, 0.80), c(0.02, 0.01, 0.80), c(0.65, 0.50, 0.85))
pc <- lapply(props, function(v) {
  r <- power.prop.test(p1 = v[1], p2 = v[2], power = v[3], sig.level = 0.05)
  pw <- power.prop.test(p1 = v[1], p2 = v[2], n = 200, sig.level = 0.05)$power
  list(p1 = v[1], p2 = v[2], power = v[3], n = r$n, power_at_200 = pw)
})
means <- list(c(5, 10, 0.80), c(2, 3, 0.90), c(0.5, 1, 0.80), c(10, 8, 0.95))
mc <- lapply(means, function(v) {
  r <- power.t.test(delta = v[1], sd = v[2], power = v[3], sig.level = 0.05)
  list(delta = v[1], sd = v[2], power = v[3], n = r$n)
})
cat(toJSON(list(note = "Generated by tests/fixtures/generators/sample_size.R (stats::power.prop.test, stats::power.t.test).",
                r_version = R.version.string, proportions = pc, means = mc), auto_unbox = TRUE, digits = NA, pretty = TRUE))
